import './v5.8.css';
import { escapeHtml, instrumentLabel, money } from './format';
import { activeCashFlows, ledgerQuantity } from './portfolio-ledger';
import type { AssetCode, CostBasisStatus, LocalPortfolio, PublicSnapshot } from './types';

function costStatusLabel(status?: CostBasisStatus): string {
  if (status === 'COMPLETE' || status === 'CONFIRMED') return '成本完整';
  if (status === 'PARTIAL' || status === 'ESTIMATED') return '成本部分可用';
  if (status === 'PENDING_RECONCILIATION') return '待核对';
  return '待建立';
}

function costStatusTone(status?: CostBasisStatus): string {
  if (status === 'COMPLETE' || status === 'CONFIRMED') return 'positive';
  if (status === 'PENDING_RECONCILIATION') return 'negative';
  return 'warning';
}

export function portfolioDialog(snapshot: PublicSnapshot, portfolio: LocalPortfolio): string {
  const today = new Date().toISOString().slice(0, 10);
  const snapshots = (portfolio.snapshots ?? []).filter((item) => !item.supersededBy);
  const positionFields = snapshot.assets.map((asset) => {
    const position = portfolio.positionsByCode?.[asset.code];
    const mode = position?.inputMode ?? 'MARKET_VALUE';
    const amount = mode === 'QUANTITY' ? position?.quantity : position?.confirmedMarketValue ?? portfolio.values[asset.code];
    const valuation = asset.valuationClose ? `¥${asset.valuationClose.toFixed(3)}` : '缺失';
    const cost = position?.remainingCostBasis;
    return `<div class="position-record" data-position-record="${asset.code}"><label><span>${escapeHtml(instrumentLabel(asset.code, asset.name))}<small>${escapeHtml(asset.role)} · 未复权估值价 ${valuation}（${escapeHtml(asset.valuationPriceDate ?? '—')}）</small></span><span class="position-input"><select name="mode-${asset.code}" data-position-mode="${asset.code}" aria-label="${escapeHtml(asset.name)}输入方式"><option value="QUANTITY" ${mode === 'QUANTITY' ? 'selected' : ''}>份额</option><option value="MARKET_VALUE" ${mode === 'MARKET_VALUE' ? 'selected' : ''}>市值</option></select><input name="${asset.code}" type="number" min="0" step="0.01" inputmode="decimal" value="${amount || ''}" placeholder="0.00"></span></label><button type="button" class="position-cost-status ${costStatusTone(position?.costBasisStatus)}" data-open-cost-code="${asset.code}"><span>${costStatusLabel(position?.costBasisStatus)}</span><strong>${cost == null ? '进入成本账本' : `${money(cost)} · 查看事件`}</strong></button></div>`;
  }).join('');

  const costAssetOptions = snapshot.assets.map((asset) => `<option value="${asset.code}">${escapeHtml(instrumentLabel(asset.code, asset.name))}</option>`).join('');
  const costPanels = snapshot.assets.map((asset) => {
    const code = asset.code as AssetCode;
    const position = portfolio.positionsByCode?.[code];
    const shares = position?.inputMode === 'QUANTITY' ? position.quantity ?? 0 : null;
    const expectedShares = ledgerQuantity(portfolio, code);
    const difference = shares == null || expectedShares == null ? null : shares - expectedShares;
    const cost = position?.remainingCostBasis;
    const averageCost = shares != null && shares > 0 && cost != null ? cost / shares : null;
    const opening = (portfolio.openingPositionEvents ?? []).find((event) => event.code === code);
    const trades = (portfolio.tradeEvents ?? []).filter((event) => event.code === code);
    const adjustments = (portfolio.positionAdjustmentEvents ?? []).filter((event) => event.code === code);
    const income = (portfolio.incomeEvents ?? []).filter((event) => event.code === code).reduce((sum, event) => sum + event.amount, 0);
    const realizedValues = trades.map((event) => event.realizedProfit).filter((value): value is number => value != null);
    const realized = trades.some((event) => event.side === 'SELL' && event.realizedProfit == null)
      ? null : realizedValues.reduce((sum, value) => sum + value, 0);
    const quantityReady = position?.inputMode === 'QUANTITY';
    const openingBlock = opening
      ? `<div class="cost-readonly"><span><small>成本起始日</small><strong>${opening.eventDate}</strong></span><span><small>初始份额</small><strong>${opening.shares.toLocaleString('zh-CN')}</strong></span><span><small>初始单位成本</small><strong>¥${opening.unitCost.toFixed(4)}</strong></span><span><small>初始含费成本</small><strong>${money(opening.totalCost)}</strong></span></div><p class="ledger-rule">初始成本已经封存。后续平均成本只由成交和调整事件滚动计算，不能直接覆盖。</p>`
      : `<div class="cost-workflow-form"><div class="workflow-heading"><div><span>首次建立成本</span><strong>录入实际份额与单位成本</strong></div><small>每只标的只需一次；总成本由系统计算</small></div><div class="cost-form-grid"><label><span>成本起始日</span><input id="opening-date-${code}" type="date" value="${today}"></label><label><span>实际持有份额</span><input id="opening-shares-${code}" type="number" min="1" step="1" inputmode="numeric" value="${shares && shares > 0 ? shares : ''}" placeholder="例如 80000"></label><label><span>初始单位成本（元）</span><input id="opening-unit-${code}" type="number" min="0" step="0.0001" inputmode="decimal" placeholder="例如 1.2460"></label><label><span>计入成本的费用（元）</span><input id="opening-fee-${code}" type="number" min="0" step="0.01" inputmode="decimal" value="0"></label><label class="wide"><span>来源或备注（可选）</span><input id="opening-note-${code}" type="text" maxlength="120" placeholder="例如：券商持仓对账单"></label></div><div class="cost-preview"><span>系统将建立</span><strong id="opening-preview-${code}">填写份额与单位成本后预览</strong></div><button type="button" class="primary" data-record-opening="${code}" ${quantityReady ? '' : 'disabled'}>确认建立成本</button>${quantityReady ? '' : '<small class="form-warning">当前是市值模式；请先在“持仓”中切换为份额并保存。</small>'}</div>`;
    const reconcileState = difference == null
      ? expectedShares == null ? '<strong class="warning">等待建立事件账本</strong><small>建立初始成本后，系统才有可核对的账本份额。</small>' : '<strong class="warning">当前持仓不是份额模式</strong><small>无法与事件账本逐份核对。</small>'
      : Math.abs(difference) < 1e-8 ? '<strong class="positive">账本与持仓一致</strong><small>无需处理，盈亏可按当前成本质量展示。</small>'
        : `<strong class="negative">相差 ${difference > 0 ? '+' : ''}${difference.toLocaleString('zh-CN')} 份</strong><small>不自动覆盖历史；请选择补录成交、登记非交易调整或暂时标记待核对。</small>`;
    const recentEvents = [
      ...trades.map((event) => ({ date: event.tradeDate, label: `${event.side === 'BUY' ? '买入' : '卖出'} ${event.shares.toLocaleString('zh-CN')} 份`, detail: `${money(event.shares * event.price)} · 费用 ${money(event.fee)}` })),
      ...adjustments.map((event) => ({ date: event.eventDate, label: `非交易调整 ${event.sharesDelta > 0 ? '+' : ''}${event.sharesDelta.toLocaleString('zh-CN')} 份`, detail: event.note || event.type })),
    ].sort((left, right) => right.date.localeCompare(left.date)).slice(0, 5);
    return `<article class="cost-ledger-asset" data-cost-asset="${code}" hidden><header class="cost-asset-head"><div><span>${escapeHtml(asset.role)}</span><h3>${escapeHtml(instrumentLabel(code, asset.name))}</h3></div><strong class="${costStatusTone(position?.costBasisStatus)}">${costStatusLabel(position?.costBasisStatus)}</strong></header><div class="cost-metrics"><span><small>当前份额</small><strong>${shares == null ? '市值模式' : shares.toLocaleString('zh-CN')}</strong></span><span><small>平均成本</small><strong>${averageCost == null ? '—' : `¥${averageCost.toFixed(4)}`}</strong></span><span><small>已实现盈亏</small><strong class="${realized != null && realized >= 0 ? 'positive' : realized != null ? 'negative' : ''}">${realized == null ? '—' : money(realized)}</strong></span><span><small>现金分红</small><strong>${money(income)}</strong></span></div>${openingBlock}
      <div class="cost-workflow-form"><div class="workflow-heading"><div><span>日常成交滚动</span><strong>只登记已经发生的真实成交</strong></div><small>登记后自动更新份额、现金和移动平均成本</small></div><div class="trade-side-switch"><button type="button" data-ledger-side="BUY" data-code="${code}" aria-pressed="true">买入</button><button type="button" data-ledger-side="SELL" data-code="${code}" aria-pressed="false">卖出</button></div><input id="trade-side-${code}" type="hidden" value="BUY"><div class="cost-form-grid"><label><span>成交日期</span><input id="trade-date-${code}" type="date" value="${today}"></label><label><span>成交份额</span><input id="trade-shares-${code}" type="number" min="1" step="1" inputmode="numeric" placeholder="真实成交份额"></label><label><span>成交价格（元）</span><input id="trade-price-${code}" type="number" min="0" step="0.001" inputmode="decimal" value="${asset.valuationClose ?? ''}"></label><label><span>佣金及费用（元）</span><input id="trade-fee-${code}" type="number" min="0" step="0.01" inputmode="decimal" value="0"></label><label class="wide"><span>说明（可选）</span><input id="trade-note-${code}" type="text" maxlength="120" placeholder="例如：按月末调仓建议自行成交"></label></div><div class="cost-preview"><span>登记后预览</span><strong id="trade-preview-${code}">填写成交份额后预览</strong></div><button type="button" class="primary" data-record-trade="${code}" ${quantityReady ? '' : 'disabled'}>登记真实成交</button></div>
      <div class="reconcile-workflow"><div class="workflow-heading"><div><span>份额核对</span><strong>券商实际持仓与事件账本</strong></div><small>系统 ${expectedShares == null ? '—' : expectedShares.toLocaleString('zh-CN')} 份 · 当前 ${shares == null ? '—' : shares.toLocaleString('zh-CN')} 份</small></div><div class="reconcile-state">${reconcileState}</div>${difference != null && Math.abs(difference) >= 1e-8 ? `<div class="adjustment-tools"><label><span>调整类型</span><select id="adjustment-type-${code}"><option value="TRANSFER_IN">转入</option><option value="TRANSFER_OUT">转出</option><option value="SPLIT_MERGE">拆分或合并</option><option value="DIVIDEND_REINVESTMENT">红利再投资</option><option value="OTHER">其他</option></select></label><label><span>份额变化</span><input id="adjustment-shares-${code}" type="number" step="1" value="${difference}"></label><label><span>转入单位成本（可选）</span><input id="adjustment-unit-${code}" type="number" min="0" step="0.0001" placeholder="拆并不填写"></label><label><span>调整日期</span><input id="adjustment-date-${code}" type="date" value="${today}"></label><label class="wide"><span>依据或说明</span><input id="adjustment-note-${code}" type="text" maxlength="120" placeholder="必须说明差异来源"></label><div class="adjustment-actions"><button type="button" class="secondary" data-backfill-trade="${code}">补录上方遗漏成交</button><button type="button" class="secondary" data-record-adjustment="${code}">登记非交易调整</button><button type="button" class="text-button" data-mark-cost-pending="${code}">暂时标记待核对</button></div><small class="wide form-warning">补录遗漏成交会使用上方成交日期、方向、份额、价格与费用，只补齐历史事件，不再次改变当前份额和现金。</small></div>` : ''}</div>
      <details class="income-disclosure"><summary><span><strong>现金分红与最近事件</strong><small>现金分红计入投资盈亏，但不改变单位成本</small></span><b>${trades.length + adjustments.length} 笔事件</b></summary><div class="income-entry"><input id="income-date-${code}" type="date" value="${today}"><input id="income-amount-${code}" type="number" min="0" step="0.01" placeholder="现金分红金额"><input id="income-note-${code}" type="text" maxlength="100" placeholder="说明（可选）"><button type="button" class="secondary" data-record-income="${code}">登记分红</button></div>${recentEvents.length ? `<ol class="cost-event-list">${recentEvents.map((event) => `<li><time>${event.date}</time><span><strong>${escapeHtml(event.label)}</strong><small>${escapeHtml(event.detail)}</small></span></li>`).join('')}</ol>` : '<p class="empty-ledger-note">尚无后续成交或调整事件。</p>'}</details></article>`;
  }).join('');

  const executionFields = snapshot.assets.map((asset) => `<div class="execution-fill" data-execution-code="${asset.code}"><span><strong>${escapeHtml(instrumentLabel(asset.code, asset.name))}</strong><small>建议份额将在打开时带入；请以真实成交为准</small></span><select name="fill-side-${asset.code}" aria-label="${asset.name}方向"><option value="BUY">买入</option><option value="SELL">卖出</option></select><input name="fill-shares-${asset.code}" type="number" min="0" step="1" inputmode="numeric" placeholder="成交份额"><input name="fill-price-${asset.code}" type="number" min="0" step="0.001" inputmode="decimal" value="${asset.valuationClose ?? ''}" placeholder="成交价"><input name="fill-fee-${asset.code}" type="number" min="0" step="0.01" inputmode="decimal" placeholder="费用"></div>`).join('');
  return `<dialog id="portfolio-dialog" aria-labelledby="portfolio-dialog-title"><form method="dialog" id="portfolio-form"><div class="dialog-head"><div><p>仅当前浏览器</p><h2 id="portfolio-dialog-title">家庭投资账本</h2></div><button type="button" data-close-dialog aria-label="关闭">×</button></div><p class="privacy">持仓决定当前配置；成本账本只根据真实事件计算盈亏。两者分开保存，都不会连接券商或自动交易。</p>
    <nav class="dialog-step-nav ledger-four-tabs" role="tablist" aria-label="账本录入步骤"><button id="ledger-tab-holdings" type="button" role="tab" aria-selected="true" aria-controls="ledger-panel-holdings" class="active" data-ledger-step-button="holdings">1 持仓</button><button id="ledger-tab-cost" type="button" role="tab" aria-selected="false" aria-controls="ledger-panel-cost" data-ledger-step-button="cost">2 成本与成交</button><button id="ledger-tab-cashflow" type="button" role="tab" aria-selected="false" aria-controls="ledger-panel-cashflow" data-ledger-step-button="cashflow">3 现金流</button><button id="ledger-tab-backup" type="button" role="tab" aria-selected="false" aria-controls="ledger-panel-backup" data-ledger-step-button="backup">4 备份</button></nav>
    <div class="record-summary"><span>资产基线 <strong>${portfolio.baseline?.date ?? '尚未建立'}</strong></span><span>有效快照 <strong>${snapshots.length}</strong></span><span>成交事件 <strong>${portfolio.tradeEvents?.length ?? 0} 笔</strong></span><span>组合现金 <strong>${money(portfolio.cash)}</strong></span></div>
    <section id="ledger-panel-holdings" class="dialog-section dialog-step active" role="tabpanel" aria-labelledby="ledger-tab-holdings" data-ledger-step="holdings"><h3>持仓与组合内现金</h3><p class="dialog-section-note">推荐使用真实份额。这里不再直接填写成本；持仓变化如来自成交，应到“成本与成交”登记事件。</p><div class="holding-fields">${positionFields}<label><span>组合内现金<small>计入总资产并参与调仓预算；应急与近期支出资金请勿录入</small></span><input name="cash" type="number" min="0" step="0.01" inputmode="decimal" value="${portfolio.cash || ''}" placeholder="0.00"></label></div></section>
    <section id="ledger-panel-cost" class="dialog-step cost-ledger-step" role="tabpanel" aria-labelledby="ledger-tab-cost" data-ledger-step="cost"><div class="cost-ledger-selector"><label for="cost-asset-select">选择标的</label><select id="cost-asset-select">${costAssetOptions}</select><p>单位成本只在首次建账录入；以后由真实成交和调整事件自动推导。</p></div>${costPanels}</section>
    <section id="ledger-panel-cashflow" class="dialog-disclosure dialog-step" role="tabpanel" aria-labelledby="ledger-tab-cashflow" data-ledger-step="cashflow"><div class="dialog-panel-head"><strong>外部现金流与更正</strong><small>仅记录新增资金或取出资金；现金分红请在成本账本登记</small></div><fieldset class="cash-flow-fields"><legend>本次是否包含已经发生的外部现金流</legend><p>ETF之间买卖和现金分红都不是外部现金流。</p><div><select name="cashFlowType"><option value="">无现金流</option><option value="CONTRIBUTION">新增资金</option><option value="WITHDRAWAL">取出资金</option></select><input name="cashFlowDate" type="date" value="${today}"><input name="cashFlowAmount" type="number" min="0" step="0.01" placeholder="金额"><input name="cashFlowNote" type="text" maxlength="80" placeholder="说明（可选）"></div></fieldset></section>
    <section id="ledger-panel-backup" class="dialog-disclosure dialog-step" role="tabpanel" aria-labelledby="ledger-tab-backup" data-ledger-step="backup"><div class="dialog-panel-head"><strong>加密备份与恢复</strong><small>事件账本随备份完整保存；导入覆盖前自动建立本机恢复点</small></div><div class="backup"><div><h3>完整账本加密备份</h3><p>导出前会执行一次加密—解密干跑校验；密码不会保存，忘记后无法恢复。</p><small>备份健康：${portfolio.backupHealth?.status ?? '未校验'} · ${escapeHtml(portfolio.backupHealth?.message ?? '尚未校验')}</small><small>最近恢复点：${portfolio.backupHealth?.lastRecoveryPointAt?.slice(0, 10) ?? '尚未建立'} · 最近恢复：${portfolio.backupHealth?.lastRestoredAt?.slice(0, 10) ?? '尚未执行'}</small></div><input class="visually-hidden" type="text" autocomplete="username" value="资产 本机备份" tabindex="-1" aria-hidden="true"><input id="backup-password" type="password" minlength="8" autocomplete="new-password" placeholder="备份密码，至少 8 个字符"><div class="backup-actions"><button type="button" class="secondary" id="export-backup">校验并导出</button><button type="button" class="secondary" id="import-backup">选择文件并预览</button>${portfolio.backupHealth?.lastRecoveryPointId ? '<button type="button" class="text-button" id="restore-recovery-point">预览导入前恢复点</button>' : ''}<input id="backup-file" type="file" accept="application/json,.json" hidden></div></div></section>
    <div id="dialog-status" class="dialog-status" aria-live="polite"></div><div class="dialog-actions" data-ledger-save-actions><button type="button" data-close-dialog class="secondary">取消</button><button type="submit" class="primary">${snapshot.health.blocking ? '仅保存本机资产记录' : '保存并重新计算'}</button></div></form></dialog>
    <dialog id="execution-dialog"><form method="dialog" id="execution-form"><div class="dialog-head"><div><p>真实成交回报 · 仅当前浏览器</p><h2>成交与现金对账</h2></div><button type="button" data-close-execution aria-label="关闭">×</button></div><p class="privacy">这不是交易入口。请在券商完成操作后抄录真实成交；成交将同时进入事件账本并按移动加权平均法更新成本。</p><input name="executionAdviceId" type="hidden"><input name="executionStatus" type="hidden"><div class="execution-meta"><label><span>成交日期</span><input name="executionTradeDate" type="date" value="${today}" required></label><label><span>成交后组合内现金</span><input name="executionCashAfter" type="number" min="0" step="0.01" required></label></div><div class="execution-fill-head"><span>标的</span><span>方向</span><span>真实份额</span><span>真实成交价</span><span>费用</span></div>${executionFields}<label class="execution-note"><span>执行说明</span><input name="executionNote" type="text" maxlength="120" placeholder="可选；例如分批成交原因"></label><div id="execution-status" class="dialog-status" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-close-execution class="secondary">取消</button><button type="submit" class="primary">校验并保存成交回报</button></div></form></dialog>
    <dialog id="restore-preview-dialog"><div class="dialog-head"><div><p>导入前预览 · 不会立即覆盖</p><h2>核对要恢复的家庭账本</h2></div><button type="button" data-cancel-restore aria-label="关闭">×</button></div><p class="privacy">确认后，系统会先把当前账本保存为独立恢复点，再导入所选备份。恢复点只保存在当前浏览器。</p><div id="restore-preview-summary" class="restore-preview-summary" aria-live="polite"></div><div class="dialog-actions"><button type="button" data-cancel-restore class="secondary">取消</button><button type="button" id="confirm-restore" class="primary">建立恢复点并导入</button></div></dialog>`;
}
